753	// ---- 持久化 ----
754	
755	// loadLocked 读取、严格解析并重放校验状态文件。调用方必须持锁。
756	func (s *Store) loadLocked() (*storedState, error) {
757		raw, err := os.ReadFile(s.path)
758		if err != nil {
759			return nil, err
760		}
761		if len(bytes.TrimSpace(raw)) == 0 {
762			return nil, fmt.Errorf("%w: %s: file is empty", ErrStateCorrupt, s.path)
763		}
764		if err := checkStateStructure(raw); err != nil {
765			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
766		}
767		var state storedState
768		dec := json.NewDecoder(bytes.NewReader(raw))
769		dec.DisallowUnknownFields()
770		if err := dec.Decode(&state); err != nil {
771			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
772		}
773		// 拒绝单个合法 JSON 之后再拼接的额外内容（如 "{} {}"）。
774		var extra json.RawMessage
775		if err := dec.Decode(&extra); err != io.EOF {
776			if err == nil {
777				err = fmt.Errorf("unexpected trailing content after state document: %s", strings.TrimSpace(string(extra)))
778			}
779			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
780		}
781		if err := validateState(&state); err != nil {
782			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
783		}
784		return &state, nil
785	}
786	
787	// commitLocked 序列化状态并以“临时文件 + fsync + 原子改名 + 目录 fsync”提交。
788	// 任一步失败都保留上次完整状态。调用方必须持锁。
789	func (s *Store) commitLocked(state *storedState) error {
790		if err := validateState(state); err != nil {
791			return fmt.Errorf("refusing to persist invalid state: %w", err)
792		}
793		payload, err := json.MarshalIndent(state, "", "  ")
794		if err != nil {
795			return err
796		}
797		payload = append(payload, '\n')
798	
799		dir := filepath.Dir(s.path)
800		tmp, err := os.CreateTemp(dir, ".govflow-state-*")
801		if err != nil {
802			return err
803		}
804		tmpName := tmp.Name()
805		cleanup := func() { _ = os.Remove(tmpName) }
806		if _, err := tmp.Write(payload); err != nil {
807			_ = tmp.Close()
808			cleanup()
809			return err
810		}
811		if err := tmp.Sync(); err != nil {
812			_ = tmp.Close()
813			cleanup()
814			return err
815		}
816		if err := tmp.Close(); err != nil {
817			cleanup()
818			return err
819		}
820		if err := os.Chmod(tmpName, 0o600); err != nil {
821			cleanup()
822			return err
823		}
824		if err := os.Rename(tmpName, s.path); err != nil {
825			cleanup()
826			return err
827		}
828		if err := syncDir(dir); err != nil {
829			return err
830		}
831		return nil
832	}
833	
834	func syncDir(dir string) error {
835		d, err := os.Open(dir)
836		if err != nil {
837			return err
838		}
839		defer d.Close()
840		return d.Sync()
841	}
842	
843	// validateState 做结构校验并重放全部凭据，确认余额与凭据完全一致。
844	func validateState(state *storedState) error {
845		if state.Magic != stateMagic {
846			return fmt.Errorf("bad magic %q", state.Magic)
847		}
848		if state.Version != stateVersion {
849			return fmt.Errorf("unsupported state version %d", state.Version)
850		}
851		if state.InitialTreasury < 0 {
852			return errors.New("initial treasury balance is negative")
853		}
854		if state.Treasury < 0 {
855			return errors.New("treasury balance is negative")
856		}
857		if state.Balances == nil {
858			return errors.New("balances table is missing")
859		}
860		if state.Proposals == nil {
861			return errors.New("proposals table is missing")
862		}
863		if state.Receipts == nil {
864			return errors.New("receipts table is missing")
865		}
866		// VoteProposals 缺省视为空表：旧版本写出的状态文件不含投票提案，继续可读。
867		if state.VoteProposals == nil {
868			state.VoteProposals = map[string]*storedVoteProposal{}
869		}
870		for account, balance := range state.Balances {
871			if account == "" {
872				return errors.New("balance entry with empty account")
873			}
874			if balance < 0 {
875				return fmt.Errorf("balance of %q is negative", account)
876			}
877		}
878		for key, p := range state.Proposals {
879			if p == nil {
880				return fmt.Errorf("proposal %q is empty", key)
881			}
882			if p.ID != key || p.ID == "" {
883				return fmt.Errorf("proposal key %q does not match id %q", key, p.ID)
884			}
885			if p.State != "passed" && p.State != "executed" {
886				return fmt.Errorf("proposal %q has unknown state %q", p.ID, p.State)
887			}
888			// 动作原文登记时原样保存；空串或非法原文留待执行时拒绝。
889		}
890		if err := validateVoteProposals(state); err != nil {
891			return err
892		}
893	
894		// 重放凭据：从初始资金库余额出发，按成功顺序重放每笔转账，
895		// 校验凭据内的前后余额、最终资金库与各账户余额，并检查状态一致性。
896		simTreasury := state.InitialTreasury
897		simBalances := map[string]int64{}
898		seenReceipts := map[string]int{}
899		for order, rcpt := range state.Receipts {
900			if rcpt == nil {
901				return fmt.Errorf("receipt %d is empty", order)
902			}
903			// order 是执行留痕中明确保存的成功提交序号（0 起），必须显式写出、
904			// 为 int64 范围内的非负整数且恰好等于凭据在记录表中的位置：第一份
905			// 凭据缺 order 也不能补成 0。缺失/空值/类型不符/位置不符都带提案
906			// 编号与字段报损坏，不按数组位置重新编号。
907			if err := validateReceiptOrder(order, rcpt); err != nil {
908				return err
909			}
910			if prev, dup := seenReceipts[rcpt.ProposalID]; dup {
911				return fmt.Errorf("duplicate receipt for %q at positions %d and %d", rcpt.ProposalID, prev, order)
912			}
913			seenReceipts[rcpt.ProposalID] = order
914			ownerState, ownerTimelock, ownerActions, found := proposalOwnerState(state, rcpt.ProposalID)
915			if !found {
916				return fmt.Errorf("receipt %q references an unregistered proposal", rcpt.ProposalID)
917			}
918			if ownerState != "executed" {
919				return fmt.Errorf("proposal %q has receipt but state is %q", rcpt.ProposalID, ownerState)
920			}
921			// 保存的凭据与首次执行受同一条执行资格规则约束：executed_at 必须明确
922			// 写出且不得早于提案时间锁。登记提案与投票提案共用这一判断。
923			if err := validateReceiptExecutedAt(order, rcpt, ownerTimelock); err != nil {
924				return err
925			}
926			// 每项动作的 index 与四个余额字段（资金库/收款账户 × before/after）
927			// 都必须明确写出：任何一个缺失、为 null 或类型不符都判整份状态损坏，
928			// 不能按数组位置、转账金额、账户余额或其它凭据补出；明确写出的 0 是
929			// 合法记录（第一项动作的 index 0 必须显式保存）。
930			for i := range rcpt.Actions {
931				if err := validateReceiptActionIndex(rcpt.ProposalID, i, &rcpt.Actions[i]); err != nil {
932					return err
933				}
934				if err := validateReceiptActionBalances(rcpt.ProposalID, i, &rcpt.Actions[i]); err != nil {
935					return err
936				}
937			}
938			// 凭据声明的逐笔转账由统一转账规则（verifyReceiptTransfers）重放
939			// 核对：动作条数/编号/原文、资金库与收款账户前后余额任一不符都带
940			// 动作位置报损坏原因；本函数随即返回错误，整份状态被拒绝，重放结果
941			// 不会被查询或落盘采纳。
942			var verr error
943			simTreasury, verr = verifyReceiptTransfers(rcpt, ownerActions, simTreasury, simBalances)
944			if verr != nil {
945				return verr
946			}
947		}
948		if simTreasury != state.Treasury {
949			return fmt.Errorf("treasury balance %d does not match receipt replay %d", state.Treasury, simTreasury)
950		}
951		if len(simBalances) != len(state.Balances) {
952			return fmt.Errorf("balance table has %d accounts, receipt replay yields %d", len(state.Balances), len(simBalances))
953		}
954		for account, balance := range state.Balances {
955			if simBalances[account] != balance {
956				return fmt.Errorf("balance of %q is %d but receipt replay yields %d", account, balance, simBalances[account])
957			}
958		}
959		// 已执行的提案必须有凭据；passed 提案不得有凭据（上面已部分保证）。
960		for _, p := range state.Proposals {
961			_, hasReceipt := seenReceipts[p.ID]
962			if p.State == "executed" && !hasReceipt {
963				return fmt.Errorf("proposal %q is executed without receipt", p.ID)
964			}
965		}
966		for _, p := range state.VoteProposals {
967			_, hasReceipt := seenReceipts[p.ID]
968			if p.State == "executed" && !hasReceipt {
969				return fmt.Errorf("voting proposal %q is executed without receipt", p.ID)
970			}
971		}
972		return nil
973	}
974	
975	// validateReceiptExecutedAt 严格判定一份已保存凭据的 executed_at：
976	// 字段未写出、显式为 null 或不是 int64 整数都返回带定位的错误；
977	// 明确写出的值必须不早于所属提案的 timelock_end（恰好等于时间锁有效，
978	// 时间锁允许 0 时明确写出的 0 同样有效）。order 是凭据在凭据表中的
979	// 位置（0 起），与提案编号一起用于定位。
980	// “缺失/空值/类型不符”的判定与逐票明细、计票结果共用同一份规则
981	// （requiredScalarProblem），此处只补充凭据的业务位置与执行资格检查。
982	func validateReceiptExecutedAt(order int, rcpt *Receipt, timelockEnd int64) error {
983		if problem := requiredScalarProblem(rcpt.executedAtRaw, scalarInteger); problem != "" {
984			return fmt.Errorf("receipt %d for proposal %q field %q %s", order, rcpt.ProposalID, "executed_at", problem)
985		}
986		if rcpt.ExecutedAt < timelockEnd {
987			return fmt.Errorf("receipt %d for proposal %q executed_at %d is before timelock_end %d",
988				order, rcpt.ProposalID, rcpt.ExecutedAt, timelockEnd)
989		}
990		return nil
991	}
992	
993	// validateReceiptOrder 严格判定一份已保存凭据的 order：它是执行留痕中明确
994	// 保存的成功提交序号（0 起），字段未写出、显式为 null 或不是 int64 整数都
995	// 返回带提案编号与字段的错误；类型合法但值与凭据在记录表中的实际位置不符
996	// （含负数）则返回位置不符的错误。第一份凭据恰好排在位置 0 也不能因此把
997	// 缺失字段补成 0——明确写出的 0 才是合法序号，缺失/null/写错类型一律拒绝。
998	// position 是凭据在凭据表中的位置（0 起）。
999	func validateReceiptOrder(position int, rcpt *Receipt) error {
1000		if problem := requiredScalarProblem(rcpt.orderRaw, scalarInteger); problem != "" {
1001			return fmt.Errorf("receipt %d for proposal %q field %q %s",
1002				position, rcpt.ProposalID, "order", problem)
1003		}
1004		if rcpt.Order != int64(position) {
1005			return fmt.Errorf("receipt %d for proposal %q field %q is %d, expected %d",
1006				position, rcpt.ProposalID, "order", rcpt.Order, position)
1007		}
1008		return nil
1009	}
1010	
1011	// validateReceiptActionIndex 严格判定一条动作留痕的 index：它是该动作在所属
1012	// 凭据中明确保存的位置编号（0 起）。字段未写出、显式为 null 或不是 int64
1013	// 整数（字符串、布尔、小数、指数写法、超界）返回带提案编号、动作位置与
1014	// 字段的错误；类型合法但值与动作的实际位置不符（含负数）返回位置不符错误。
1015	// 第一项动作缺失 index 不得被补成 0：只有明确写出的 0 才合法。position 是
1016	// 动作在凭据 actions 中的位置（0 起）。
1017	func validateReceiptActionIndex(id string, position int, ar *ActionReceipt) error {
1018		if problem := requiredScalarProblem(ar.indexRaw, scalarInteger); problem != "" {
1019			return fmt.Errorf("receipt for proposal %q action %d field %q %s",
1020				id, position, "index", problem)
1021		}
1022		if ar.Index != int64(position) {
1023			return fmt.Errorf("receipt for proposal %q action %d field %q is %d, expected %d",
1024				id, position, "index", ar.Index, position)
1025		}
1026		return nil
1027	}
1028	
1029	// validateReceiptActionBalances 严格判定一条动作留痕的四个余额字段：
1030	// 资金库与收款账户两侧的 before/after 都必须明确写出、非 null 且为 int64
1031	// 整数。任何一个字段缺失都判整份状态损坏，不能根据转账金额、账户余额或
1032	// 其它凭据补出它——即使按其余记录推算该字段本来应为 0。明确写出的整数 0
1033	// 是合法记录（如资金库恰好扣到 0、收款账户首次收款前为 0），不得当成缺失。
1034	// index 是动作在凭据中的下标（0 起），与提案编号、所在侧一起用于定位。
1035	// “缺失/空值/类型不符”的判定与逐票明细、计票结果、executed_at 共用同一份
1036	// 规则（validateRawFields），此处只补充业务位置：提案编号 + 动作下标 + 侧。
1037	func validateReceiptActionBalances(id string, index int, ar *ActionReceipt) error {
1038		sides := []struct {
1039			name   string
1040			update *BalanceUpdate
1041		}{
1042			{"treasury", &ar.Treasury},
1043			{"recipient", &ar.Recipient},
1044		}
1045		for _, side := range sides {
1046			err := validateRawFields([]rawField{
1047				{name: "before", kind: scalarInteger, raw: side.update.beforeRaw},
1048				{name: "after", kind: scalarInteger, raw: side.update.afterRaw},
1049			}, func(field, problem string) error {
1050				return fmt.Errorf("receipt for proposal %q action %d %s field %q %s",
1051					id, index, side.name, field, problem)
1052			})
1053			if err != nil {
1054				return err
1055			}
1056		}
1057		return nil
1058	}
1059	
1060	// ---- 结构检查：固定字段名逐字匹配 + 重复键拒绝 ----
1061	
1062	// schemaKind 是状态文件 JSON 在某一层的形状类别。
1063	type schemaKind int
1064	
1065	const (
1066		kindAny     schemaKind = iota // 叶子值：结构检查不深入，类型由解码器核对
1067		kindObject                    // 固定字段对象：键必须与保存格式的字段名逐字一致
1068		kindMap                       // 业务编号表：键是自由文本（账户名、提案编号）
1069		kindArray                     // 数组
1070		kindString                    // 叶子：必须是 JSON 字符串
1071		kindBoolean                   // 叶子：必须是 JSON 布尔值（不接受字符串/数字/null）
1072		kindInteger                   // 叶子：必须是 int64 范围内的 JSON 整数（不接受小数/指数/字符串/null）
1073	)
1074	
1075	// schemaNode 描述状态文件某一层允许的形状。整棵树由 storedState 的 json tag
1076	// 反射生成，字段名集合因此永远与保存格式一致，不会随结构演进而漂移。
1077	type schemaNode struct {
1078		kind   schemaKind
1079		fields map[string]*schemaNode // kindObject：字段名 → 值的形状
1080		elem   *schemaNode            // kindMap/kindArray：值/元素的形状
1081	}
1082	
1083	// schemaOf 按 encoding/json 的字段名规则（json tag 优先，缺省用字段名）推导形状。
1084	func schemaOf(t reflect.Type) *schemaNode {
1085		for t.Kind() == reflect.Pointer {
1086			t = t.Elem()
1087		}
1088		switch t.Kind() {
1089		case reflect.Struct:
1090			node := &schemaNode{kind: kindObject, fields: map[string]*schemaNode{}}
1091			for i := 0; i < t.NumField(); i++ {
1092				f := t.Field(i)
1093				if f.PkgPath != "" { // 未导出字段不参与 JSON
1094					continue
1095				}
1096				name := f.Name
1097				if tag, ok := f.Tag.Lookup("json"); ok {
1098					tagName, _, _ := strings.Cut(tag, ",")
1099					if tagName == "-" {
1100						continue
1101					}
1102					if tagName != "" {
1103						name = tagName
1104					}
1105				}
1106				node.fields[name] = schemaOf(f.Type)
1107			}
1108			return node
1109		case reflect.Map:
1110			return &schemaNode{kind: kindMap, elem: schemaOf(t.Elem())}
1111		case reflect.Slice, reflect.Array:
1112			return &schemaNode{kind: kindArray, elem: schemaOf(t.Elem())}
1113		case reflect.String:
1114			return &schemaNode{kind: kindString}
1115		case reflect.Bool:
1116			return &schemaNode{kind: kindBoolean}
1117		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
1118			reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
1119			return &schemaNode{kind: kindInteger}
1120		default:
1121			return &schemaNode{kind: kindAny}
1122		}
1123	}
1124	
1125	var storedStateSchema = schemaOf(reflect.TypeOf(storedState{}))
1126	
1127	func init() {
1128		// 票据的四个标量字段（representative/weight/support/voted_at）由
1129		// validateStoredBallot 逐票判定“缺失/空值/类型不符”，其错误原因需要带上
1130		// 提案编号、票据下标与字段名；因此结构扫描在这些叶子位置保持宽松（kindAny），
1131		// 不抢在解码器之前用不含票据定位的通用信息报错。
1132		ballotFields := storedStateSchema.fields["vote_proposals"].elem.fields["ballots"].elem.fields
1133		for _, name := range []string{"representative", "weight", "support", "voted_at"} {
1134			ballotFields[name].kind = kindAny
1135		}
1136		// 计票结果的两个权重字段（for_weight/against_weight）同理：缺失/空值/
1137		// 类型不符的判定需要带上提案编号，统一由 validateStoredTally 报错，
1138		// 结构扫描在这两个叶子位置保持宽松。tallied_at 保持严格整数叶子，
1139		// 其“不早于截止”的既有校验不变。
1140		tallyFields := storedStateSchema.fields["vote_proposals"].elem.fields["tally"].fields
1141		for _, name := range []string{"for_weight", "against_weight"} {
1142			tallyFields[name].kind = kindAny
1143		}
1144		// 凭据的 executed_at 同理：缺失/空值/类型不符/早于时间锁的判定需要带上
1145		// 提案编号与凭据位置，统一由 validateReceiptExecutedAt 报错，结构扫描在此
1146		// 叶子位置保持宽松。
1147		receiptFields := storedStateSchema.fields["receipts"].elem.fields
1148		receiptFields["executed_at"].kind = kindAny
1149		// 凭据的 order 同理：缺失/空值/类型不符/位置不符的判定需要带上提案编号与
1150		// 凭据位置，统一由 validateReceiptOrder 报错，结构扫描在此叶子位置保持宽松。
1151		receiptFields["order"].kind = kindAny
1152		// 凭据逐笔留痕的 index 同理：缺失/空值/类型不符/位置不符的判定需要带上
1153		// 提案编号与动作下标，统一由 validateReceiptActionIndex 报错，结构扫描在
1154		// 此叶子位置保持宽松。
1155		receiptFields["actions"].elem.fields["index"].kind = kindAny
1156		// 凭据逐笔留痕的四个余额字段（treasury/recipient 的 before/after）同理：
1157		// 缺失/空值/类型不符的判定需要带上提案编号、动作下标与所在侧，统一由
1158		// validateReceiptActionBalances 报错，结构扫描在这些叶子位置保持宽松。
1159		actionFields := receiptFields["actions"].elem.fields
1160		for _, side := range []string{"treasury", "recipient"} {
1161			balanceFields := actionFields[side].fields
1162			balanceFields["before"].kind = kindAny
1163			balanceFields["after"].kind = kindAny
1164		}
1165	}
1166	
1167	// scanFrame 是结构扫描的栈帧。
1168	type scanFrame struct {
1169		node    *schemaNode
1170		isArray bool
1171		opaque  bool // 形状不符或叶子位置的容器：只配对括号，类型错误交给解码器报告
1172		seen    map[string]bool
1173		atValue bool // 对象帧：下一个待消费 token 是值而非键
1174		index   int  // 数组帧：下一个元素下标
1175		path    string
1176	}
1177	
1178	func peekFrame(stack []*scanFrame) *scanFrame {
1179		if len(stack) == 0 {
1180			return nil
1181		}
1182		return stack[len(stack)-1]
1183	}
1184	
1185	// checkStateStructure 在解码前逐 token 扫描状态文件：
1186	//   - 同一对象内键（按 JSON 解读后的字符串，转义拼写与普通拼写视为同一键）不得重复；
1187	//   - 固定字段对象的键必须与保存格式的字段名逐字一致：大小写变体（如 Treasury、
1188	//     Support）与未知字段一样拒绝，避免解码器的大小写折叠把两份值并入同一字段；
1189	//   - balances/proposals/vote_proposals 等业务编号表的键是自由文本，
1190	//     Audit 与 audit、GIP-1 与 gip-1 是不同账户/编号，不做字段名检查。
1191	//
1192	// 报错带有出问题的字段与所在记录的路径（如 vote_proposals["GIP-1"].ballots[0]），
1193	// 便于定位。字段顺序、缩进与合法转义不影响判定。
1194	func checkStateStructure(raw []byte) error {
1195		dec := json.NewDecoder(bytes.NewReader(raw))
1196		// UseNumber：数字 token 保留词面写法，整数叶子可据此精确判定 int64 范围，
1197		// 不被 float64 在 2^63 附近的舍入混淆（MaxInt64 与 MaxInt64+1 会折成同一浮点）。
1198		dec.UseNumber()
1199		var stack []*scanFrame
1200		// 对象帧读到键时，把该键对应值的形状与路径暂存于此，供紧随其后的值使用。
1201		pendingNode := storedStateSchema
1202		pendingPath := "state"
1203	
1204		// 一个值消费完毕：推进父帧的键/值位置或数组下标。
1205		finishValue := func() {
1206			top := peekFrame(stack)
1207			if top == nil || top.opaque {
1208				return
1209			}
1210			if top.isArray {
1211				top.index++
1212			} else {
1213				top.atValue = false
1214			}
1215		}
1216	
1217		for {
1218			tok, err := dec.Token()
1219			if err == io.EOF {
1220				if len(stack) != 0 {
1221					return errors.New("unterminated object or array")
1222				}
1223				return nil
1224			}
1225			if err != nil {
1226				return err
1227			}
1228	
1229			if top := peekFrame(stack); top != nil && top.opaque {
1230				// 不透明容器内不做字段检查，只配对括号。
1231				if d, ok := tok.(json.Delim); ok {
1232					if d == '{' || d == '[' {
1233						stack = append(stack, &scanFrame{opaque: true})
1234					} else {
1235						stack = stack[:len(stack)-1]
1236						finishValue()
1237					}
1238				}
1239				continue
1240			}
1241	
1242			if top := peekFrame(stack); top != nil && !top.isArray && !top.atValue {
1243				// 对象帧的键位置：闭括号或下一个键。
1244				if d, ok := tok.(json.Delim); ok {
1245					if d != '}' {
1246						return fmt.Errorf("unexpected %q inside object at %s", string(d), top.path)
1247					}
1248					stack = stack[:len(stack)-1]
1249					finishValue()
1250					continue
1251				}
1252				key, ok := tok.(string)
1253				if !ok {
1254					return errors.New("object key must be a string")
1255				}
1256				if top.seen[key] {
1257					return fmt.Errorf("duplicate key %q at %s", key, top.path)
1258				}
1259				top.seen[key] = true
1260				top.atValue = true
1261				switch top.node.kind {
1262				case kindObject:
1263					child, known := top.node.fields[key]
1264					if !known {
1265						return fmt.Errorf("unknown field %q at %s", key, top.path)
1266					}
1267					pendingNode = child
1268					pendingPath = top.path + "." + key
1269				case kindMap:
1270					// 业务编号是自由文本，大小写变体属于不同编号，不得拒绝或合并。
1271					pendingNode = top.node.elem
1272					pendingPath = top.path + "[" + strconv.Quote(key) + "]"
1273				}
1274				continue
1275			}
1276	
1277			// 值位置：对象键之后的值或数组元素。
1278			node := pendingNode
1279			path := pendingPath
1280			if top := peekFrame(stack); top != nil && top.isArray {
1281				node = top.node.elem
1282				path = top.path + "[" + strconv.Itoa(top.index) + "]"
1283			}
1284			if d, ok := tok.(json.Delim); ok {
1285				switch d {
1286				case '{', '[':
1287					frame := &scanFrame{isArray: d == '[', path: path}
1288					shapeOK := (d == '{' && (node.kind == kindObject || node.kind == kindMap)) ||
1289						(d == '[' && node.kind == kindArray)
1290					if !shapeOK {
1291						// 叶子位置出现容器或形状不符：跳过内容，类型错误由解码器报告。
1292						frame.opaque = true
1293					} else {
1294						frame.node = node
1295						if d == '{' {
1296							frame.seen = map[string]bool{}
1297						}
1298					}
1299					stack = append(stack, frame)
1300				default: // '}' 或 ']'：数组结束（对象的闭括号已在键位置处理）
1301					if len(stack) == 0 {
1302						return errors.New("unexpected closing delimiter")
1303					}
1304					stack = stack[:len(stack)-1]
1305					finishValue()
1306				}
1307				continue
1308			}
1309			// 标量值（含 null）：严格叶子必须与字段声明的 JSON 类型逐字一致，
1310			// null 不允许用来顶替字符串/布尔/整数。
1311			if err := checkLeafScalar(node, path, tok); err != nil {
1312				return err
1313			}
1314			finishValue()
1315		}
1316	}
1317	
1318	// leafKindName 是严格叶子类型在错误信息中的人类可读名称。
1319	func leafKindName(k schemaKind) string {
1320		switch k {
1321		case kindString:
1322			return "string"
1323		case kindBoolean:
1324			return "boolean"
1325		case kindInteger:
1326			return "integer"
1327		default:
1328			return "value"
1329		}
1330	}
1331	
1332	// tokenKindName 归类一个标量 token 实际写出的 JSON 类型。
1333	func tokenKindName(tok json.Token) string {
1334		switch v := tok.(type) {
1335		case nil:
1336			return "null"
1337		case string:
1338			return "string"
1339		case bool:
1340			return "boolean"
1341		case json.Number:
1342			if _, err := strconv.ParseInt(string(v), 10, 64); err == nil {
1343				return "integer"
1344			}
1345			return "number"
1346		default:
1347			return "value"
1348		}
1349	}
1350	
1351	// checkLeafScalar 校验严格标量叶子：字符串/布尔/int64 整数位置出现 null 或
1352	// 其它 JSON 类型即判结构损坏。非整数（小数、指数）或超出 int64 的整数同样拒绝。
1353	func checkLeafScalar(node *schemaNode, path string, tok json.Token) error {
1354		switch node.kind {
1355		case kindString, kindBoolean, kindInteger:
1356		default:
1357			return nil
1358		}
1359		if node.kind == kindInteger {
1360			if n, ok := tok.(json.Number); ok {
1361				if _, err := strconv.ParseInt(string(n), 10, 64); err != nil {
1362					return fmt.Errorf("field at %s must be an int64 integer, got %s", path, string(n))
1363				}
1364				return nil
1365			}
1366		}
1367		want := leafKindName(node.kind)
1368		if got := tokenKindName(tok); got != want {
1369			return fmt.Errorf("field at %s must be %s, got %s", path, want, got)
1370		}
1371		return nil
1372	}
1373

