256	func runCreateVote(args []string) {
257		cf := newCmdFlags("create-vote")
258		id := cf.fs.String("id", "", "proposal id (non-empty)")
259		var members memberList
260		cf.fs.Var(&members, "member", "member ID:WEIGHT with positive int64 weight (repeatable, order irrelevant to equality)")
261		var delegations delegationList
262		cf.fs.Var(&delegations, "delegate", "delegation FROM:TO (repeatable, order irrelevant to equality)")
263		quorumRaw := cf.fs.String("quorum", "", "required turnout weight between 1 and total member weight")
264		startRaw := cf.fs.String("start", "", "voting start timestamp (int64, >= 0)")
265		deadlineRaw := cf.fs.String("deadline", "", "voting deadline timestamp (int64, > start)")
266		timelockRaw := cf.fs.String("timelock", "", "timelock end timestamp (int64, >= deadline)")
267		var actions actionList
268		cf.fs.Var(&actions, "action", "action text transfer:<account>:<amount> (repeatable, order preserved)")
269		cf.parse(args)
270		if *id == "" {
271			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
272			os.Exit(2)
273		}
274		quorum := parseIntFlag(cf.fs, "quorum", *quorumRaw)
275		start := parseIntFlag(cf.fs, "start", *startRaw)
276		deadline := parseIntFlag(cf.fs, "deadline", *deadlineRaw)
277		timelock := parseIntFlag(cf.fs, "timelock", *timelockRaw)
278		if len(members) == 0 {
279			fmt.Fprintf(os.Stderr, "usage error: at least one --member ID:WEIGHT is required\n")
280			os.Exit(2)
281		}
282	
283		store, err := govflow.Open(cf.state)
284		if err != nil {
285			fail(err)
286		}
287		defer store.Close()
288		in := &govflow.CreateVoteInput{
289			ID:          *id,
290			Members:     []govflow.VoteMember(members),
291			Delegations: []govflow.Delegation(delegations),
292			Quorum:      quorum,
293			StartAt:     start,
294			Deadline:    deadline,
295			TimelockEnd: timelock,
296			Actions:     []string(actions),
297		}
298		view, existed, err := store.CreateVoteProposal(in)
299		if err != nil {
300			fail(err)
301		}
302		if cf.asJSON {
303			emitJSON(map[string]any{"proposal": view, "already_exists": existed})
304			return
305		}
306		if existed {
307			fmt.Printf("voting proposal %s already exists with identical content (state=%s)\n", view.ID, view.State)
308		} else {
309			fmt.Printf("created voting proposal %s: %d member(s), total_weight=%d, quorum=%d, voting=[%d,%d), timelock_end=%d, %d action(s)\n",
310				view.ID, len(view.Members), view.TotalWeight, view.Quorum, view.StartAt, view.Deadline, view.TimelockEnd, len(view.Actions))
311		}
312	}
