317	func TestCorruptStateRejected(t *testing.T) {
318		dir := t.TempDir()
319		path := filepath.Join(dir, "treasury.json")
320		store, err := InitTreasury(path, 100)
321		if err != nil {
322			t.Fatal(err)
323		}
324		mustRegister(t, store, "gip-1", 0, "transfer:a:10")
325		if _, err := store.Execute("gip-1", 0); err != nil {
326			t.Fatal(err)
327		}
328		store.Close()
329	
330		good, err := os.ReadFile(path)
331		if err != nil {
332			t.Fatal(err)
333		}
334		corruptions := map[string][]byte{
335			"truncated":      good[:len(good)/2],
336			"garbage":        []byte("not json at all"),
337			"empty":          []byte(""),
338			"bad magic":      bytesReplaceAll(good, []byte(stateMagic), []byte("something-else")),
339			"dup key":        dupKeyInject(good),
340			"trailing json":  append(append([]byte{}, good...), []byte(" {}")...),
341			"balance tamper": bytesReplaceAll(good, []byte("\"treasury\": 90"), []byte("\"treasury\": 9999")),
342		}
343		for name, raw := range corruptions {
344			t.Run(name, func(t *testing.T) {
345				bad := filepath.Join(dir, "corrupt-"+name+".json")
346				if err := os.WriteFile(bad, raw, 0o600); err != nil {
347					t.Fatal(err)
348				}
349				s, err := Open(bad)
350				if !errors.Is(err, ErrStateCorrupt) {
351					if s != nil {
352						s.Close()
353					}
354					t.Fatalf("Open corrupt(%s) err=%v, want ErrStateCorrupt", name, err)
355				}
356				// 损坏文件没有被覆盖或重建。
357				if got, rerr := os.ReadFile(bad); rerr != nil || (len(raw) > 0 && !equalBytes(got, raw)) {
358					t.Fatalf("corrupt file was modified for %s", name)
359				}
