14	// TestPlanTransfersChainsBalances：统一转账规则按动作原顺序扣款/加款，
15	// 未出现过的收款账户从零开始，同一账户连续收款时后一笔承接前一笔结果，
16	// 金额恰好等于资金库剩余余额时扣款到 0 仍成功。
17	func TestPlanTransfersChainsBalances(t *testing.T) {
18		steps, treasury, balances, err := planTransfers(
19			[]string{"transfer:audits:250", "transfer:audits:100", "transfer:legal:50"},
20			1000, nil)
21		if err != nil {
22			t.Fatalf("planTransfers: %v", err)
23		}
24		want := []struct {
25			acct           string
26			tb, ta, rb, ra int64
27		}{
28			{"audits", 1000, 750, 0, 250},
29			{"audits", 750, 650, 250, 350}, // 同一账户连续收款
30			{"legal", 650, 600, 0, 50},
31		}
32		for i, w := range want {
33			st := steps[i]
34			if st.account != w.acct || st.treasuryBefore != w.tb || st.treasuryAfter != w.ta ||
35				st.recipientBefore != w.rb || st.recipientAfter != w.ra || st.failure != nil {
36				t.Fatalf("step %d = %+v, want acct=%s treasury=%d->%d recipient=%d->%d",
37					i, st, w.acct, w.tb, w.ta, w.rb, w.ra)
38			}
39			if got := st.actionReceipt(i, "transfer:"+w.acct+":x"); got.Treasury.Account != "treasury" ||
40				got.Recipient.Account != w.acct || got.Index != int64(i) {
41				t.Fatalf("actionReceipt shape wrong: %+v", got)
42			}
43		}
44		if treasury != 600 {
45			t.Fatalf("treasury = %d, want 600", treasury)
46		}
47		if balances["audits"] != 350 || balances["legal"] != 50 || len(balances) != 2 {
48			t.Fatalf("balances = %+v, want audits=350 legal=50", balances)
49		}
50	
51		// 起始状态中已有的账户余额被承接，且起始表不被修改。
52		start := map[string]int64{"audits": 7}
53		steps, treasury, balances, err = planTransfers([]string{"transfer:audits:3"}, 10, start)
54		if err != nil {
55			t.Fatalf("planTransfers existing: %v", err)
56		}
57		if steps[0].recipientBefore != 7 || steps[0].recipientAfter != 10 ||
58			treasury != 7 || balances["audits"] != 10 {
59			t.Fatalf("existing balance not carried: %+v %d %+v", steps[0], treasury, balances)
60		}
61		if start["audits"] != 7 {
62			t.Fatalf("planTransfers mutated starting balances: %+v", start)
63		}
64	
65		// 金额恰好等于资金库剩余余额：可以成功，资金库扣到 0。
66		steps, treasury, _, err = planTransfers([]string{"transfer:x:10"}, 10, nil)
67		if err != nil || treasury != 0 || steps[0].treasuryAfter != 0 {
68			t.Fatalf("exact-remaining transfer rejected: %v treasury=%d steps=%+v", err, treasury, steps)
69		}
70	}
71	
72	// TestPlanTransfersFailurePrecedence：动作非法、收款溢出、资金库不足的
73	// 分类、动作位置与先报告顺序沿用首次执行路径的既有行为；同一动作同时
74	// 触发收款溢出与资金库不足时先报告溢出。
75	func TestPlanTransfersFailurePrecedence(t *testing.T) {
76		// 动作格式错误：同时匹配 ErrExecutionRejected 与 ErrInvalidAction。
77		_, _, _, err := planTransfers([]string{"transfer:a:1", "withdraw:b:2"}, 1000, nil)
78		if !errors.Is(err, ErrExecutionRejected) || !errors.Is(err, ErrInvalidAction) {
79			t.Fatalf("malformed err=%v, want both sentinels", err)
80		}
81		if !strings.Contains(err.Error(), `action 1 ("withdraw:b:2")`) {
82			t.Fatalf("malformed error lost position/text: %v", err)
83		}
84	
85		// 收款溢出先于资金库不足：资金库只剩 5、账户已接近 int64 上限，
86		// 一笔 10 同时满足两个条件，必须先报溢出并带动作位置。
87		nearMax := map[string]int64{"a": math.MaxInt64 - 5}
88		_, _, _, err = planTransfers([]string{"transfer:a:10"}, 5, nearMax)
89		if !errors.Is(err, ErrExecutionRejected) || errors.Is(err, ErrInvalidAction) {
90			t.Fatalf("overflow err=%v, want ErrExecutionRejected only", err)
91		}
92		if !strings.Contains(err.Error(), "recipient balance overflow at action 0") ||
93			!strings.Contains(err.Error(), "account=a") {
94			t.Fatalf("overflow error wrong/reordered: %v", err)
95		}
96	
97		// 资金库不足（无溢出）：文案与位置保持不变。
98		_, _, _, err = planTransfers([]string{"transfer:mida:600", "transfer:midb:500"}, 1000, nil)
99		if !errors.Is(err, ErrExecutionRejected) ||
100			!strings.Contains(err.Error(), "insufficient treasury balance at action 1") {
101			t.Fatalf("insufficient err=%v", err)
102		}
103	}
104	
105	// TestVerifyReceiptTransfersAcceptsPlannedAndRejectsTamper：执行预演产出的
